where session_id = #{sessionId}
  and status = 'success'
  and role in ('user', 'assistant')
  and request_id in (
    select request_id from (
        select request_id
        from law_chat_message
        where session_id = #{sessionId}
          and status = 'success'
          and role = 'assistant'
        group by request_id
        order by max(id) desc
        limit #{limit}
    ) recent
  )
order by id asc

