insert into law_chat_message (
    session_id, request_id, role, content, status, error_code, model_name, citations_json,
    rewritten_query, retrieval_mode, tool_calls_json, prompt_tokens, completion_tokens, total_tokens,
    ttft_ms, total_latency_ms, create_time, update_time
) values (
    #{sessionId}, #{requestId}, #{role}, #{content}, #{status}, #{errorCode}, #{modelName},
    #{citationsJson}, #{rewrittenQuery}, #{retrievalMode}, #{toolCallsJson}, #{promptTokens},
    #{completionTokens}, #{totalTokens}, #{ttftMs}, #{totalLatencyMs}, #{createTime}, #{updateTime}
)

mapper.update:
update law_chat_message
set status = 'failed',
    error_code = 'timeout_recovered',
    update_time = #{now}
where session_id = #{sessionId}
  and role = 'assistant'
  and status = 'pending'
  and create_time < #{deadline}
